-- Conteúdos-tipo dos cursos (texto do site e módulos por omissão), antes fixos no frontend.
-- `padrao` diz a que cursos se aplica: "ccp" e "comunicar" casam com o nome do curso;
-- "ufcd:<código>" casa com o código UFCD. Editáveis pela equipa; o frontend lê-os da API.
CREATE TABLE IF NOT EXISTS conteudos_modelo (
  chave text PRIMARY KEY,
  tipo text NOT NULL CHECK (tipo IN ('site', 'modulos')),
  regime text NOT NULL CHECK (regime IN ('gold', 'fin')),
  padrao text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE conteudos_modelo ENABLE ROW LEVEL SECURITY;
ALTER TABLE conteudos_modelo FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS gesforma_api ON conteudos_modelo;
CREATE POLICY gesforma_api ON conteudos_modelo FOR ALL
  USING (current_setting('gesforma.api', true) = '1')
  WITH CHECK (current_setting('gesforma.api', true) = '1');

INSERT INTO conteudos_modelo (chave, tipo, regime, padrao, payload) VALUES
('site:ccp', 'site', 'gold', 'ccp', '{"sintese":"O CCP - Certificado de Competências Pedagógicas - é a credenciação oficial para exercer a profissão de formador em Portugal.\n\n90 horas em b-learning: sessões presenciais/síncronas, trabalho em plataforma e simulação pedagógica inicial e final. No fim, o formando está preparado para planear, conduzir e avaliar formação de adultos.","objetivos":"Compreender o sistema de formação de adultos e o papel do formador.\nPlanear sessões com objetivos, métodos e recursos adequados.\nConduzir grupos com técnicas ativas e gestão do tempo.\nConstruir e aplicar instrumentos de avaliação.\nRealizar uma simulação pedagógica completa, da planificação ao feedback.","programa":"M1 · Aprendizagem e pedagogia - 20h\nM2 · Comunicação e dinâmica de grupos - 20h\nM3 · Avaliação da formação - 15h\nM4 · Simulação pedagógica - 25h\nM5 · Plataformas digitais e e-learning - 10h","funcionamento":"Regime b-learning: sábados de manhã ou pós-laboral, consoante a turma.\nPlataforma Moodle para materiais, fóruns e entregas (PIP e simulações).\nSimulação inicial e final gravadas em vídeo, com folha de avaliação do curso.\nAssiduidade mínima de 90% e aprovação nas simulações para emissão do CCP.","tags":"ccp, formadores, iefp"}'::jsonb),
('site:comunicar', 'site', 'gold', 'comunicar', '{"sintese":"Modalidade B-learning pensada para quem precisa de falar em público com clareza e presença - em reuniões, formações ou palco.\n\nCombina 3 aulas virtuais síncronas com trabalho autónomo em vídeo e exercícios práticos. No final, recebe certificado ENA e um percurso concreto para continuar a treinar a voz e a estrutura do discurso.","objetivos":"Dominar técnicas para respirar e potencializar a voz.\nEstruturar um discurso claro, persuasivo e adaptado ao público.\nGerir o nervosismo e a linguagem corporal em contexto real.\nUsar pausas, ênfase e contacto visual de forma intencional.\nDar e receber feedback construtivo sobre apresentações.","programa":"Aula Virtual 1 - Técnicas para respirar e potencializar a voz\n• Respiração diafragmática e apoio vocal\n• Articulação, projeção e ritmo\n• Exercícios práticos em grupo\n\nAula Virtual 2 - Estrutura do discurso e presença cénica\n• Abertura, desenvolvimento e fecho\n• Storytelling e exemplos pessoais\n• Linguagem corporal e gestão do espaço\n\nAula Virtual 3 - Ensaio e feedback\n• Apresentação de 3 minutos\n• Grelha de observação entre pares\n• Plano de melhoria individual","funcionamento":"3 videoconferências de 2h, em grupos até 10 formandos.\n8 horas de trabalho autónomo em plataforma (vídeos, exercícios e fórum).\nMateriais digitais disponíveis após cada sessão.\nSuporte técnico por email durante o curso.\nCertificado emitido com 80% de assiduidade e exercício final entregue.","tags":"comunicacao, voz, b-learning"}'::jsonb),
('site:ufcd:3564', 'site', 'fin', 'ufcd:3564', '{"categoria":"Saúde e segurança","tags":"primeiros socorros, saude, ufcd","sintese":"UFCD 3564 do Catálogo Nacional de Qualificações. Forma para reconhecer emergências, aplicar suporte básico de vida e estabilizar a vítima até chegar ajuda especializada.\n\n25 horas em e-learning, com casos práticos e avaliação final. Curso financiado - sem custo para o formando elegível.","objetivos":"Identificar sinais de emergência médica e acionar o 112.\nAplicar a cadeia de sobrevivência e o SBV no adulto.\nControlar hemorragias e imobilizar lesões músculo-esqueléticas.\nAgir em situações de queimadura, intoxicação e desmaio.\nRegistar a ocorrência e comunicar com os meios de socorro.","programa":"1. Enquadramento e cadeia de sobrevivência\n2. Avaliação da vítima e posição de segurança\n3. Suporte básico de vida e DEA\n4. Hemorragias, feridas e queimaduras\n5. Traumatismos e imobilização\n6. Avaliação e encerramento","funcionamento":"25 horas assíncronas na plataforma Moodle.\nAcesso durante o período da turma, com tutoragem por formador.\nAssiduidade e teste final obrigatórios para certificado.\nFinanciado - sujeito a critérios de elegibilidade (IEFP / PO)."}'::jsonb),
('site:ufcd:9188', 'site', 'fin', 'ufcd:9188', '{"categoria":"TIC e cibersegurança","tags":"ciberseguranca, tic, ufcd","sintese":"UFCD 9188 - Fundamentos de cibersegurança. Introduz ameaças comuns, higiene digital e o papel de cada colaborador na proteção da organização.\n\n25 horas em b-learning: sessões síncronas para exercícios e trabalho autónomo na plataforma.","objetivos":"Reconhecer phishing, malware e engenharia social.\nAplicar palavras-passe fortes e autenticação de dois fatores.\nProteger dados pessoais e profissionais no dia a dia.\nSaber a quem reportar um incidente.\nAdotar boas práticas em dispositivos móveis e cloud.","programa":"1. Conceitos e ameaças atuais\n2. Identidade, acessos e palavras-passe\n3. Correio, ligações e ficheiros suspeitos\n4. Dispositivos, redes e cópias de segurança\n5. Resposta a incidentes e comunicação\n6. Exercício de simulação e fecho","funcionamento":"Sessões síncronas + trabalho na Moodle (25h no total).\nExercício prático de identificação de ameaças.\nFinanciado. Certificado com assiduidade e exercício entregue."}'::jsonb),
('site:ufcd:10394', 'site', 'fin', 'ufcd:10394', '{"categoria":"Formação de formadores","tags":"pedagogia, formadores, ufcd","sintese":"UFCD 10394 - Métodos e Técnicas Pedagógicas Ativos. Destina-se a formadores que querem sair do expositivo e pôr o grupo a trabalhar.\n\n25 horas em b-learning, com micro-práticas em sessão e um plano de sessão entregue no fim.","objetivos":"Escolher métodos ativos adequados ao objetivo e ao grupo.\nDesenhar atividades de 10 a 40 minutos com materiais simples.\nConduzir brainstorming, estudo de caso e role-play.\nDar feedback sem desmotivar o formando.\nIntegrar técnicas ativas num plano de sessão completo.","programa":"1. Aprendizagem de adultos e o método ativo\n2. Técnicas de abertura e quebra-gelo\n3. Trabalho de grupo, caso e simulação\n4. Questionamento e condução de plenário\n5. Avaliação formativa em sessão\n6. Plano de sessão com técnicas ativas","funcionamento":"B-learning: sessões síncronas + entregas na plataforma.\nO plano de sessão final usa os parâmetros de avaliação desta UFCD.\nFinanciado. Certificado com assiduidade e plano entregue."}'::jsonb),
('site:ufcd:10785', 'site', 'fin', 'ufcd:10785', '{"categoria":"Marketing digital","tags":"redes sociais, trafego, ufcd","sintese":"UFCD 10785 - Publicidade nas Redes Sociais. Percurso prático para planear, lançar e ler campanhas de tráfego pago em Meta e Google.\n\n25 horas em e-learning. O nome comercial no site (Master em Tráfego) deve explicar o benefício; o código UFCD fica visível para quem precisa do CNQ.","objetivos":"Definir público, objetivo e orçamento de uma campanha.\nMontar conjuntos de anúncios e criativos para feed e stories.\nLer métricas de alcance, CPC e conversão.\nAjustar campanhas com base em dados da primeira semana.\nCumprir as regras de publicidade das plataformas.","programa":"1. Ecossistema de anúncios sociais\n2. Estrutura de conta, pixel e eventos\n3. Criativos e copy para cada formato\n4. Segmentação e orçamento\n5. Leitura de relatórios e otimização\n6. Projeto final: campanha completa","funcionamento":"25 horas em e-learning com entregas semanais.\nContas de anúncios de exercício fornecidas pela ENA quando necessário.\nFinanciado. Certificado com assiduidade e projeto entregue."}'::jsonb),
('modulos:ccp', 'modulos', 'gold', 'ccp', '{"modulos":["M1 · Formador: sistemas, contextos e perfil","M2 · Simulação pedagógica inicial","M3 · Comunicação e dinamização de grupos","M4 · Metodologias e estratégias pedagógicas","M5 · Operacionalização da formação","M6 · Recursos didáticos e multimédia","M7 · Plataformas colaborativas e de aprendizagem","M8 · Avaliação da formação e das aprendizagens","M9 · Simulação pedagógica final"]}'::jsonb),
('modulos:ufcd:3564', 'modulos', 'fin', 'ufcd:3564', '{"modulos":["UFCD 3564 · Avaliação primária e SVB","UFCD 3564 · Trauma e hemorragias","UFCD 3564 · Queimaduras e intoxicações","UFCD 3564 · Emergências médicas","UFCD 3564 · Simulação e avaliação"]}'::jsonb)
ON CONFLICT (chave) DO NOTHING;
